{
  "references": [
    {
      "id": "R1",
      "summary_ko": "아이와 뱀들이 하늘에 있고 뱀이 구름으로 변함"
    },
    {
      "id": "R2",
      "summary_ko": "피리 위 소년의 오른손 손가락 수가 3개 또는 5개로 바뀜"
    },
    {
      "id": "R3",
      "summary_ko": "뱀이 구름으로 만들어져 있지 않음(구름 형태의 뱀)"
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "왼쪽 코브라의 머리가 줄어들며 구름 속으로 사라짐"
    },
    {
      "id": "C2",
      "summary_ko": "왼쪽 뱀을 감싸는 구름이 부자연스럽게 팽창하고 끓어오르며 색 밀도가 변함"
    },
    {
      "id": "C3",
      "summary_ko": "왼쪽 뱀의 머리가 상체를 덮은 부자연스러운 구름 속으로 변형되며 사라짐"
    },
    {
      "id": "C4",
      "summary_ko": "피리를 부는 아이의 일관되지 않은 손가락 위치 및 그립 변화"
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "same",
      "reason_ko": "뱀이 구름으로 변하여 사라지는 현상을 동일하게 설명합니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 뱀이 구름으로 변하는 결함이고, C2는 뱀 주위 구름 자체의 비정상적인 움직임과 색 밀도 변화를 설명합니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "same",
      "reason_ko": "뱀의 머리가 구름으로 변형되며 사라지는 동일한 결함을 기술하고 있습니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "뱀의 변형과 아이의 손가락 결함으로 대상과 현상이 완전히 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "피리를 잡은 손가락 결함과 뱀 머리가 사라지는 현상으로 대상이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "손가락 개수 변화와 구름의 비정상적 변화로 대상과 내용이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "손가락 개수 결함과 뱀 머리의 소멸 현상으로 서로 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "verdict": "same",
      "reason_ko": "피리를 연주하는 아이의 손가락 형태 및 파지법의 일관성 없는 변화를 다루고 있어 실질적으로 같은 결함입니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "R3의 뱀이 구름 형태라는 언급이 C1의 뱀 머리가 구름으로 변형되는 현상과 관련이 있는지 모호합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R3은 뱀의 재질/형태에 관한 것이고, C2는 구름의 팽창 및 색 밀도 변화를 다룹니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C3",
      "verdict": "uncertain",
      "reason_ko": "R3의 뱀이 구름으로 되어 있다는 설명과 C3의 구름 속으로 변형/소멸한다는 내용의 일치 여부가 불분명합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "뱀의 구름 재질 결함과 아이의 손가락 결함으로 대상이 완전히 다릅니다."
    }
  ]
}
